<?php declare(strict_types=1); namespace Modules\Products\Controllers; use App\Http\Controllers\Controller; use Core\Http\JsonResponse; use Core\Http\Request; use Modules\Products\Services\ProductMediaService; use Modules\Products\Services\ProductService; class ProductMediaController extends Controller { public function __construct( private readonly ProductService $products, private readonly ProductMediaService $media, ) { } public function store(Request $request, int $id): JsonResponse { $this->products->find($id); $section = (string) $request->input('section', 'photos'); $attachments = []; $failed = []; foreach ($this->uploadedFiles($request) as $file) { try { $attachmentId = $this->media->upload($id, $file, $section); if ($attachmentId > 0) { $attachments[] = $this->media->attachmentPayload($attachmentId); } } catch (\Throwable $exception) { $failed[] = $exception->getMessage(); } } if ($attachments === [] && $failed !== []) { return $this->json(['success' => false, 'message' => $failed[0], 'errors' => $failed], 422); } return $this->json([ 'success' => true, 'message' => trans('products.media_uploaded'), 'data' => ['attachments' => $attachments, 'errors' => $failed], ]); } public function replaceSection(Request $request, int $id): JsonResponse { $this->products->find($id); $section = (string) $request->input('section', 'photos'); $files = $this->uploadedFiles($request); if ($files === []) { return $this->json(['success' => false, 'message' => trans('products.media_file_required')], 422); } try { $result = $this->media->replaceSection($id, $section, $files); } catch (\Throwable $exception) { return $this->json(['success' => false, 'message' => $exception->getMessage()], 422); } if ($result['attachments'] === [] && $result['errors'] !== []) { return $this->json(['success' => false, 'message' => $result['errors'][0], 'errors' => $result['errors']], 422); } return $this->json([ 'success' => true, 'message' => trans('products.media_section_replaced'), 'data' => $result, ]); } public function replace(Request $request, int $id, int $attachmentId): JsonResponse { $this->products->find($id); $file = $request->file('image'); if (!is_array($file) || (int) ($file['error'] ?? UPLOAD_ERR_NO_FILE) === UPLOAD_ERR_NO_FILE) { return $this->json(['success' => false, 'message' => trans('products.media_file_required')], 422); } try { $payload = $this->media->replace($attachmentId, $file); } catch (\Throwable $exception) { return $this->json(['success' => false, 'message' => $exception->getMessage()], 422); } return $this->json([ 'success' => true, 'message' => trans('products.media_replaced'), 'data' => $payload, ]); } public function move(Request $request, int $id, int $attachmentId): JsonResponse { $payload = $request->jsonPayload() ?? $request->all(); $section = (string) (is_array($payload) ? ($payload['section'] ?? 'photos') : 'photos'); try { $this->media->move($attachmentId, $section); } catch (\Throwable $exception) { return $this->json(['success' => false, 'message' => $exception->getMessage()], 422); } return $this->json([ 'success' => true, 'message' => trans('products.media_moved'), 'data' => $this->media->attachmentPayload($attachmentId), ]); } public function primary(int $id, int $attachmentId): JsonResponse { try { $this->media->makePrimary($attachmentId); } catch (\Throwable $exception) { return $this->json(['success' => false, 'message' => $exception->getMessage()], 422); } return $this->json([ 'success' => true, 'message' => trans('products.media_primary_set'), 'data' => $this->media->attachmentPayload($attachmentId), ]); } public function order(Request $request, int $id, int $attachmentId): JsonResponse { $payload = $request->jsonPayload() ?? $request->all(); $direction = (string) (is_array($payload) ? ($payload['direction'] ?? 'up') : 'up'); $this->media->reorder($attachmentId, $direction); return $this->json(['success' => true, 'message' => trans('products.media_reordered')]); } public function destroy(int $id, int $attachm